      ],
      "name changes": []
    },
    "System Administration": {
      "derived from": "System Administration Subdomain",
      "objects": [
        "System Administrator",
        "Bike Usage Data",
        "Bike Delivery",
        "Delivered Bike",
        "Bike Delivery Worker"
      ],
      "name changes": [
        "Bike -> Delivered Bike"
      ]
    },
    "Station Management": {
      "derived from": "Station Management Subdomain",
      "objects": [
        "Bike Station",
        "Location",
        "Availability Status",
        "Bike",
        "Dock",
        "Docking Station Manager"
      ],
      "name changes": [
        "Bike Station stays Bike Station",
        "Bike stays Bike"
      ]
    },
    "Bike Maintenance": {
      "derived from": "Bike Maintenance Subdomain",
      "objects": [
        "Maintenance Worker",
        "Bike Inspection",
        "Repair Log"
      ],
      "name changes": []
    },
    "Bike Renting": {
      "derived from": "Bike Renting Subdomain",
      "objects": [
        "City Resident",
